    scene::CastScene arrow;scene::Mesh mesh;mesh.name="authoritative_heading";mesh.color={.1f,.9f,.2f,1};mesh.doubleSided=true;for(const auto p:{scene::Vec3{0,-height*.035f,0},scene::Vec3{height*.65f,-height*.035f,0},scene::Vec3{height*.65f,-height*.10f,0},scene::Vec3{height*.85f,0,0},scene::Vec3{height*.65f,height*.10f,0},scene::Vec3{height*.65f,height*.035f,0},scene::Vec3{0,height*.035f,0}}){scene::Vertex v;v.position=p;v.normal={0,0,1};mesh.vertices.push_back(v);}mesh.indices={0,1,5,0,5,6,2,3,4};arrow.meshes.push_back(mesh);arrow.bounds=actor.bounds;
